<template><div class="page"><div class="page-heading"><div><h1>采购订单</h1><p>跟踪订单采购、到货和入库状态。</p></div></div><el-card class="panel-card"><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="orderNo" label="订单编号" width="190" /><el-table-column prop="requestNo" label="关联申请" width="170" /><el-table-column prop="supplier" label="供应商" min-width="210" /><el-table-column prop="amount" label="订单金额" width="140"><template #default="{ row }">¥ {{ Number(row.amount || 0).toLocaleString() }}</template></el-table-column><el-table-column prop="status" label="状态" width="110"><template #default="{ row }"><StatusTag :status="row.status" /></template></el-table-column><el-table-column prop="createTime" label="下单时间" width="175" /><el-table-column label="操作" width="130"><template #default="{ row }"><el-button v-if="row.status === 'DELIVERED'" link type="primary" @click="receive(row)">确认入库</el-button><el-button v-else link @click="detail = row; visible = true">详情</el-button></template></el-table-column><template #empty><el-empty description="暂无采购订单" /></template></el-table></el-card></div><el-dialog v-model="visible" title="订单详情" width="520px"><el-descriptions v-if="detail" border :column="2"><el-descriptions-item label="订单编号">{{ detail.orderNo }}</el-descriptions-item><el-descriptions-item label="供应商">{{ detail.supplier }}</el-descriptions-item><el-descriptions-item label="金额">¥ {{ detail.amount }}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag :status="detail.status" /></el-descriptions-item></el-descriptions></el-dialog></template>
<script setup>
import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { api } from '../api'; import StatusTag from '../components/StatusTag.vue'
const rows = ref([]); const loading = ref(false); const visible = ref(false); const detail = ref(null); async function load() { loading.value = true; try { const data = await api.orders(); rows.value = data?.records || data?.data?.records || data || [] } finally { loading.value = false } } async function receive(row) { await api.receiveOrder(row.id); ElMessage.success('已确认入库，库存已更新'); load() } onMounted(load)
</script>
